function shortestCut(arr: number[]): number {
  const n = arr.length;
  let best = n;
  for (let i = 0; i <= n; i++) {
    for (let j = i; j <= n; j++) {
      // delete arr[i..j-1]
      let prev = -Infinity, ok = true;
      for (let k = 0; k < n && ok; k++) {
        if (k >= i && k < j) continue;
        if (arr[k] < prev) ok = false;
        prev = arr[k];
      }
      if (ok) best = Math.min(best, j - i);
    }
  }
  return best;
}

