        n = len(arr)
        best = n
        for i in range(n + 1):
            for j in range(i, n + 1):
                rest = arr[:i] + arr[j:]
                if all(rest[k] <= rest[k + 1] for k in range(len(rest) - 1)):
                    best = min(best, j - i)
        return best

