function shortestCut(arr: number[]): number {
  const n = arr.length;
  let right = n - 1;
  while (right > 0 && arr[right - 1] <= arr[right]) right--;
  if (right === 0) return 0;
  let best = right; // keep only the suffix
  let j = right;
  for (let i = 0; i === 0 || arr[i - 1] <= arr[i]; i++) {
    while (j < n && arr[j] < arr[i]) j++;
    best = Math.min(best, j - i - 1);
  }
  return best;
}

